#include "Parser.h"
#include "ScriptHost.h"
#include <fstream>
#include <iostream>
#include <iterator>
#include <string>
int main(int argc,char**argv){if(argc!=3)return 2;const auto path=std::filesystem::absolute(argv[2]);std::ifstream f(path);std::string source((std::istreambuf_iterator<char>(f)),{});ScriptRenderHost host(path.parent_path());TrackedInfo tracked;auto capture=std::make_shared<ExecutionOutput>(true);Parser parser(host,tracked,capture);RenderResult r;if(std::string(argv[1])=="template"||std::string(argv[1])=="content"){RenderSource input;input.path=path;if(std::string(argv[1])=="content"){RenderSource wrapper;wrapper.path=path.parent_path()/"outer.html";r=parser.render_composed(wrapper,input,true);}else r=parser.render_composed(input,std::nullopt,false);}else r=parser.run_script(source,path);auto out=nift::RuntimeValue::make_object();out.object.emplace_back("stdout",nift::RuntimeValue(capture->stdout_text()));out.object.emplace_back("ok",nift::RuntimeValue(r.ok));out.object.emplace_back("path",nift::RuntimeValue(r.error.source_file.generic_string()));out.object.emplace_back("line",nift::RuntimeValue(static_cast<int>(r.error.line)));out.object.emplace_back("column",nift::RuntimeValue(static_cast<int>(r.error.column)));out.object.emplace_back("source_length",nift::RuntimeValue(static_cast<int>(r.error.source_length)));out.object.emplace_back("excerpt",nift::RuntimeValue(r.error.source_line));out.object.emplace_back("message",nift::RuntimeValue(r.error.message));if(r.diagnostic){auto&d=*r.diagnostic;out.object.emplace_back("disposition",nift::RuntimeValue(nift::detail::diagnostic_code_info(d.code).disposition==nift::detail::DiagnosticDisposition::Recoverable?"recoverable":"fatal"));out.object.emplace_back("code",nift::RuntimeValue(std::string(nift::detail::diagnostic_code_info(d.code).text)));out.object.emplace_back("diagnostic_path",nift::RuntimeValue(d.origin.source.generic_string()));out.object.emplace_back("diagnostic_line",nift::RuntimeValue(static_cast<int>(d.origin.line)));out.object.emplace_back("diagnostic_column",nift::RuntimeValue(static_cast<int>(d.origin.column)));out.object.emplace_back("diagnostic_length",nift::RuntimeValue(static_cast<int>(d.origin.source_length)));out.object.emplace_back("diagnostic_excerpt",nift::RuntimeValue(d.origin.source_line));auto frames=nift::RuntimeValue::make_array();for(const auto&frame:d.frames){auto value=nift::RuntimeValue::make_object();value.object.emplace_back("kind",nift::RuntimeValue(static_cast<int>(frame.kind)));value.object.emplace_back("label",nift::RuntimeValue(frame.label));value.object.emplace_back("prefix",nift::RuntimeValue(frame.compatibility_prefix));value.object.emplace_back("path",nift::RuntimeValue(frame.site.source.generic_string()));value.object.emplace_back("line",nift::RuntimeValue(static_cast<int>(frame.site.line)));value.object.emplace_back("column",nift::RuntimeValue(static_cast<int>(frame.site.column)));frames.push_back(std::move(value));}out.object.emplace_back("frames",std::move(frames));}std::cout<<out.dump()<<"\n";return 0;}
